import{_ as e,o,c as a,a3 as d}from"./chunks/framework.BLaSdaBb.js";const k=JSON.parse('{"title":"工作流","description":"","frontmatter":{},"headers":[],"relativePath":"backend/workflow.md","filePath":"backend/workflow.md","lastUpdated":1786258579000}'),s={name:"backend/workflow.md"};function r(n,t,l,c,i,p){return o(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h1><p><code>XiHan.BasicApp.Workflow</code> 是四个一等业务模块之一，坐落在框架 <a href="https://framework.docs.xihanfun.com/packages/workflow" target="_blank" rel="noreferrer">工作流引擎</a> 之上，把「图执行引擎」变成一套可运营的审批/流程系统：定义能在管理端建、实例能在页面上看和干预、待办能办理和转办、状态落库不怕重启。</p><blockquote><p>引擎本身的机制（书签、活动、表达式、定时器）见 <a href="https://framework.docs.xihanfun.com/packages/workflow" target="_blank" rel="noreferrer">框架 · Workflow</a>。本页只讲 BasicApp 这一层加了什么。</p></blockquote><h2 id="模块做了什么" tabindex="-1">模块做了什么 <a class="header-anchor" href="#模块做了什么" aria-label="Permalink to &quot;模块做了什么&quot;">​</a></h2><p>模块类 <code>[DependsOn]</code> 同时挂 <code>XiHanBasicAppSaasModule</code> 与 <code>XiHanWorkflowModule</code>，<code>ConfigureServices</code> 只有三行：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddWorkflowStores</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ① Replace 掉框架的内存存储</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddWorkflowDataSeeders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ② 权限与菜单种子（Order 300–304）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddWorkflowEventHandlers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ③ 待办通知</span></span></code></pre></div><p>仓储与应用服务全部交给约定注册。<strong>这是仓库里最干净的独立模块样板</strong>——要照着做一个新模块，读它比读 AI 模块省力。</p><h3 id="_1-存储持久化-最关键的一层" tabindex="-1">① 存储持久化（最关键的一层） <a class="header-anchor" href="#_1-存储持久化-最关键的一层" aria-label="Permalink to &quot;① 存储持久化（最关键的一层）&quot;">​</a></h3><p>框架默认的三个存储是<strong>进程内内存实现，进程一停全丢</strong>。BasicApp 用 <code>Replace</code> 换成 SqlSugar 落库：</p><table tabindex="0"><thead><tr><th>框架接口</th><th>BasicApp 实现</th><th>表</th></tr></thead><tbody><tr><td><code>IWorkflowDefinitionStore</code></td><td><code>SqlSugarWorkflowDefinitionStore</code></td><td><code>Sys_Workflow_Definition</code></td></tr><tr><td><code>IWorkflowInstanceStore</code></td><td><code>SqlSugarWorkflowInstanceStore</code></td><td><code>Sys_Workflow_Instance</code> + <code>Sys_Workflow_Node_Instance</code></td></tr><tr><td><code>IWorkflowBookmarkStore</code></td><td><code>SqlSugarWorkflowBookmarkStore</code></td><td><code>Sys_Workflow_Bookmark</code></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">必须用 <code>Replace</code></p><p>框架 <code>AddXiHanWorkflow</code> 已经 <code>TryAddSingleton</code> 了内存实现，你再 <code>TryAdd</code> 会被静默忽略——表现是「重启后流程全没了」而没有任何报错。</p></div><p>落库之后才谈得上<strong>崩溃恢复</strong>：进程重启后定时器 Worker 能重新捞到到期书签，挂起中的实例继续往下走。</p><h3 id="_2-权限与菜单" tabindex="-1">② 权限与菜单 <a class="header-anchor" href="#_2-权限与菜单" aria-label="Permalink to &quot;② 权限与菜单&quot;">​</a></h3><p>权限码是独立命名空间 <code>workflow:*</code>（不是 <code>saas:*</code>）：</p><table tabindex="0"><thead><tr><th>权限码</th><th>用途</th></tr></thead><tbody><tr><td><code>workflow:read</code></td><td>查看定义 / 实例 / 待办</td></tr><tr><td><code>workflow:create</code></td><td>新建定义</td></tr><tr><td><code>workflow:update</code></td><td>编辑草稿、发布、新版本、停用、归档</td></tr><tr><td><code>workflow:delete</code></td><td>删除定义</td></tr><tr><td><code>workflow:execute</code></td><td>发起实例、干预实例（取消/终止/重试）</td></tr></tbody></table><p>种子链 <code>Order</code> 300–304，顺序恒为「操作 300 → 资源 301 → 权限 302 → 菜单 303 → 角色授权 304」，默认<strong>仅授超管</strong>。</p><p>菜单由模块自己的 <code>PageRegistry</code> 驱动：</p><table tabindex="0"><thead><tr><th>页面</th><th>路由</th><th>权限</th></tr></thead><tbody><tr><td>我的待办</td><td><code>/workflow/todo</code></td><td>无（受理人服务端锁定为当前用户）</td></tr><tr><td>流程定义</td><td><code>/workflow/definition</code></td><td><code>workflow:read</code></td></tr><tr><td>流程实例</td><td><code>/workflow/instance</code></td><td><code>workflow:read</code></td></tr></tbody></table><h3 id="_3-待办通知" tabindex="-1">③ 待办通知 <a class="header-anchor" href="#_3-待办通知" aria-label="Permalink to &quot;③ 待办通知&quot;">​</a></h3><p>三个本地事件处理器，经 <code>AddWorkflowLocalEventHandler&lt;T&gt;</code> 登记进 <code>XiHanLocalEventBusOptions.Handlers</code>：</p><ul><li>待办<strong>创建</strong> → 站内通知受理人</li><li>待办<strong>转办</strong> → 通知新受理人</li><li>实例<strong>故障</strong> → 通知相关人</li></ul><div class="warning custom-block"><p class="custom-block-title">裸 <code>AddTransient</code> 不会被订阅</p><p>本地事件总线只自动发现「以接口为服务类型」的注册。加新处理器必须走 <code>AddWorkflowLocalEventHandler&lt;T&gt;()</code>，否则静默不触发。</p></div><h2 id="三个页面能做什么" tabindex="-1">三个页面能做什么 <a class="header-anchor" href="#三个页面能做什么" aria-label="Permalink to &quot;三个页面能做什么&quot;">​</a></h2><h3 id="流程定义-workflow-definition" tabindex="-1">流程定义（<code>/workflow/definition</code>） <a class="header-anchor" href="#流程定义-workflow-definition" aria-label="Permalink to &quot;流程定义（\`/workflow/definition\`）&quot;">​</a></h3><p>定义的生命周期是一条状态链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draft 草稿 ──发布──► Published 已发布 ──停用──► Disabled 已停用 ──► Archived 已归档</span></span>
<span class="line"><span>   ▲                      │</span></span>
<span class="line"><span>   └──── 新版本 ◄─────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>操作</th><th>应用服务方法</th><th>约束</th></tr></thead><tbody><tr><td>新建</td><td><code>CreateAsync</code></td><td>建出来是 <code>Draft</code></td></tr><tr><td>编辑</td><td><code>UpdateDraftAsync</code></td><td><strong>只能改草稿</strong>，已发布的不能直接改</td></tr><tr><td>发布</td><td><code>PublishAsync</code></td><td><strong>只有已发布的定义才能启动实例</strong></td></tr><tr><td>新版本</td><td><code>NewVersionAsync</code></td><td>基于现有定义开一个新版本草稿</td></tr><tr><td>停用</td><td><code>DisableAsync</code></td><td>不可启动新实例，<strong>存量实例继续运行</strong></td></tr><tr><td>归档</td><td><code>ArchiveAsync</code></td><td>彻底下架</td></tr></tbody></table><p>定义本身是<strong>可序列化的纯数据</strong>（节点 + 连线 + 变量），所以能落库、能在管理端编辑，改流程不需要改代码重新部署。</p><h3 id="流程实例-workflow-instance" tabindex="-1">流程实例（<code>/workflow/instance</code>） <a class="header-anchor" href="#流程实例-workflow-instance" aria-label="Permalink to &quot;流程实例（\`/workflow/instance\`）&quot;">​</a></h3><p>分页查询 + 详情（<strong>含变量、执行历史与待恢复等待点</strong>），以及四个干预动作：</p><table tabindex="0"><thead><tr><th>动作</th><th>语义</th></tr></thead><tbody><tr><td>发起 <code>StartAsync</code></td><td>当前用户为发起人；同步链路能走多远走多远，可能一次调用就直接完成</td></tr><tr><td>取消 <code>CancelAsync</code></td><td>删书签、取消挂起节点；<strong>定义启用补偿时按执行逆序补偿</strong></td></tr><tr><td>终止 <code>TerminateAsync</code></td><td>强制结束，<strong>不执行补偿</strong>、不可恢复</td></tr><tr><td>重试 <code>RetryAsync</code></td><td>从故障节点重新执行</td></tr></tbody></table><p>取消与终止在实例已处于终态时<strong>幂等返回</strong>，不会报错。</p><p>实例状态：<code>Running</code>（含等待书签的空闲态）/ <code>Suspended</code> / <code>Completed</code> / <code>Canceled</code> / <code>Faulted</code>（可重试）/ <code>Terminated</code>。</p><h3 id="我的待办-workflow-todo" tabindex="-1">我的待办（<code>/workflow/todo</code>） <a class="header-anchor" href="#我的待办-workflow-todo" aria-label="Permalink to &quot;我的待办（\`/workflow/todo\`）&quot;">​</a></h3><p><strong>受理人与办理人都由服务端锁定为当前用户</strong>，所以这个页面不需要额外权限码——你只能看到和办理属于自己的待办。</p><table tabindex="0"><thead><tr><th>动作</th><th>说明</th></tr></thead><tbody><tr><td>办理 <code>CompleteAsync</code></td><td>同意 / 拒绝 / 自定义结果，可带意见与附加变量</td></tr><tr><td>转办</td><td>把任务移交给新受理人（转办后原受理人的办理动作会被拒绝）</td></tr><tr><td>加签</td><td>追加受理人</td></tr></tbody></table><p>办理结果除内置的 <code>approved</code> / <code>rejected</code> / <code>timeout</code> 外<strong>允许自定义</strong>——配合连线条件即可做多路分支（如「退回补充材料」走一条单独的线）。</p><p>完成策略由节点配置决定：<strong>或签</strong>（任一同意即通过、任一拒绝即拒绝）、<strong>会签</strong>（全部同意才通过、任一拒绝一票否决）、<strong>依次审批</strong>（按顺序逐一）。</p><h2 id="典型接入姿势" tabindex="-1">典型接入姿势 <a class="header-anchor" href="#典型接入姿势" aria-label="Permalink to &quot;典型接入姿势&quot;">​</a></h2><p>业务系统接工作流通常是这样：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务写侧（如报销申请提交）</span></span>
<span class="line"><span>   │ 落业务表（状态=审批中）</span></span>
<span class="line"><span>   │ 调 IWorkflowEngine.StartAsync(定义编码, 变量, CorrelationId=业务单号)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>流程跑到 UserTask 节点 → 写 UserTask 书签 → 实例挂起（不占线程）</span></span>
<span class="line"><span>   │ 事件处理器发站内通知给受理人</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>受理人在「我的待办」办理 → CompleteAsync → 引擎恢复书签继续推进</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>流程走到 End → 实例 Completed</span></span>
<span class="line"><span>   │ 业务侧订阅实例完成事件（或流程里用 PublishEvent 活动）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>回写业务表（状态=已通过/已驳回）</span></span></code></pre></div><p>两个建议：</p><ul><li><strong>用 <code>CorrelationId</code> 挂业务单号</strong>，这样按业务单反查流程实例、或用 <code>PublishSignalAsync</code> 定向唤醒都很自然。</li><li><strong>业务状态以业务表为准</strong>，流程实例只驱动流转。不要把业务状态只存在流程变量里——查询、报表、权限都会很难做。</li></ul><h2 id="运维注意" tabindex="-1">运维注意 <a class="header-anchor" href="#运维注意" aria-label="Permalink to &quot;运维注意&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>定时器开关</strong></td><td><code>XiHan:Workflow:Worker:IsTimerEnabled</code> 关掉后，延时 / 重试 / 节点超时书签<strong>永不自动恢复</strong>，只有人工任务与信号还能推进流程</td></tr><tr><td><strong>集群单活</strong></td><td>定时器 Worker 靠分布式锁保证集群内单活；分布式锁来自 Caching，<strong>未接 Redis 时会退化为进程内锁</strong>，多实例会各跑各的</td></tr><tr><td><strong>环路防护</strong></td><td>单批次最大节点执行数（默认 1000）、子流程最大嵌套深度（默认 16）都有硬上限，坏定义不会把进程转死</td></tr><tr><td><strong>并发</strong></td><td>引擎对同一实例的所有操作以分布式锁保证单写者；抢锁超时会抛 <code>WorkflowLockTimeoutException</code></td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="https://framework.docs.xihanfun.com/packages/workflow" target="_blank" rel="noreferrer">框架 · Workflow</a>：引擎机制、内置活动、配置项、代码方式定义流程</li><li><a href="https://framework.docs.xihanfun.com/packages/workflow-abstractions" target="_blank" rel="noreferrer">框架 · Workflow.Abstractions</a>：定义模型与存储端口</li><li><a href="./approval">审批与约束</a>：另一套更轻的审批（<code>SysReview</code>）与 RBAC 约束规则引擎</li><li><a href="./data-model#工作流">数据模型</a>：四张表</li><li><a href="./messaging">消息中心</a>：待办通知的投递通道</li></ul>`,47)])])}const g=e(s,[["render",r]]);export{k as __pageData,g as default};
